function normLogoName(name) {
  return String(name || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ');
}

/** Crest URL for a team we have indexed. Null when the name is unknown or ambiguous. */
export function logoForTeam(name, sport) {
  const table = LOGO_INDEX[String(sport || '').toUpperCase()];
  if (!table) return null;
  const key = normLogoName(name);
  if (!key) return null;
  if (table[key]) return table[key];
  const parts = key.split(' ').filter(Boolean);
  if (parts.length >= 2) {
    const two = parts.slice(-2).join(' ');
    if (table[two]) return table[two];
    const last = parts[parts.length - 1];
    if (last.length > 3 && table[last]) return table[last];
  }
  return null;
}
